import { inheritTrustedHostToolProvenance } from "../../tool/host-tool-provenance.js";
import { toChildRunToolInputRecord } from "../child-run/execution-support.js";
import { createUnconfirmedProjectContextSwitchResult, getConfirmedProjectContextSwitch, isClaimedSuccessfulProjectContextSwitchResult, } from "../project/context.js";
import { getProjectSteeringMutation, isSuccessfulProjectSteeringMutationResult, } from "../project/steering-mutation.js";
/** Wrap hosted child steering mutation tool helper. */
export function wrapHostedChildSteeringMutationTool(input) {
    if (!input.toolDefinition.execute) {
        return input.toolDefinition;
    }
    const originalExecute = input.toolDefinition.execute;
    return inheritTrustedHostToolProvenance(input.toolDefinition, {
        ...input.toolDefinition,
        execute: async (toolInput, execOptions) => {
            const normalizedToolInput = toChildRunToolInputRecord(toolInput);
            const result = await originalExecute(toolInput, execOptions);
            if (isSuccessfulProjectSteeringMutationResult(result)) {
                const mutation = getProjectSteeringMutation({
                    toolName: input.toolName,
                    toolInput: normalizedToolInput,
                    activeProjectId: input.activeProjectId,
                    activeBranchId: input.activeBranchId,
                    steeringPaths: input.steeringPaths,
                });
                if (mutation.instructionsChanged || mutation.skillsChanged) {
                    await input.onMutation?.(mutation);
                }
            }
            return result;
        },
    });
}
/** Wrap hosted child project switch tool helper. */
export function wrapHostedChildProjectSwitchTool(input) {
    const toolName = input.toolName ?? "studio_open_project";
    const toolDefinition = input.tools[toolName];
    if (!toolDefinition?.execute) {
        return;
    }
    const originalExecute = toolDefinition.execute;
    input.tools[toolName] = inheritTrustedHostToolProvenance(toolDefinition, {
        ...toolDefinition,
        execute: async (toolInput, execOptions) => {
            const normalizedToolInput = toChildRunToolInputRecord(toolInput);
            const result = await originalExecute(toolInput, execOptions);
            const projectReference = normalizedToolInput.project_reference;
            const confirmedProject = typeof projectReference === "string"
                ? getConfirmedProjectContextSwitch(result, projectReference)
                : null;
            if (confirmedProject) {
                await input.onConfirmedProjectSwitch(confirmedProject.projectId, confirmedProject);
                return result;
            }
            return isClaimedSuccessfulProjectContextSwitchResult(result)
                ? createUnconfirmedProjectContextSwitchResult()
                : result;
        },
    });
}
